## ORM（Object Relation Mapping）

**对象关系模型**
关系模型（数据库表）：   表、字段、字段类型
对象模型（java实体类）：类、属性、属性类型
通过ORM框架解除模型之间的阻抗。

## 利用反射实现ORM中的准备预编译SQL语句

1. 自定义注解：

Column.java:

```java
package com.xzy.ORM.annotation;

import java.lang.annotation.ElementType;
import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;
import java.lang.annotation.Target;

@Target(ElementType.FIELD)//指定标注位置为属性上
@Retention(RetentionPolicy.RUNTIME)//指定在运行期间有效
public @interface Column {
    //配置映射字段名称
    String name();
}
```

PK.java:

```java
package com.xzy.ORM.annotation;

import java.lang.annotation.ElementType;
import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;
import java.lang.annotation.Target;

@Target(ElementType.FIELD)//指定标注位置为字段上
@Retention(RetentionPolicy.RUNTIME)//指定在运行期间有效
public @interface PK {
    //是否自动增长，默认为true
    boolean isAuto() default true;
}
```

table.java:

```java
package com.xzy.ORM.annotation;

import java.lang.annotation.ElementType;
import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;
import java.lang.annotation.Target;

/**
 * 注意：
 * 1、注解标注的位置
 * 2、注解作用域
 */
@Target(ElementType.TYPE)//指定标注位置为类上
@Retention(RetentionPolicy.RUNTIME)//指定在运行期间有效
public @interface Table {
    String name();
}
```

2. 实体类：User.java

```java
package com.xzy.ORM.entity;

import com.xzy.ORM.annotation.Column;
import com.xzy.ORM.annotation.PK;
import com.xzy.ORM.annotation.Table;

import java.io.Serializable;

/**
 * 用户实体类
 */
@Table(name = "users")
public class User implements Serializable {

    @PK(isAuto = false)
    @Column(name = "user_id")
    private Integer id;

    @Column(name = "user_name")
    private String name;

    private String email;
    private String country;

    @Column(name = "user_password")
    private String password;


    public void setId(int id) {
        this.id = id;
    }

    public Integer getId() {
        return id;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public String getEmail() {
        return email;
    }

    public void setEmail(String email) {
        this.email = email;
    }

    public String getCountry() {
        return country;
    }

    public void setCountry(String country) {
        this.country = country;
    }

    public String getPassword() {
        return password;
    }

